fn numpy_where(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // Ensure all input vectors have the same length
    assert_eq!(condition.len(), x.len(), "condition and x must have the same length");
    assert_eq!(x.len(), y.len(), "x and y must have the same length");

    // Pre‐allocate the result with the known capacity
    let mut result = Vec::with_capacity(condition.len());

    // Consume the inputs via into_iter, zipping them together
    for ((cond, xi), yi) in condition.into_iter().zip(x.into_iter().zip(y.into_iter())) {
        // Push xi if cond is true, otherwise yi
        result.push(if cond { xi } else { yi });
    }

    result
}

